<script setup lang="ts">import{ref,onMounted}from 'vue';import{listAudits}from '../api/audits';import type{Audit}from '../types/domain';import{useTask}from '../hooks/useTask';import{dateTime}from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const items=ref<Audit[]>([]);const{error,execute}=useTask();const refresh=()=>execute(async()=>{items.value=await listAudits()});onMounted(refresh);</script><template><PageHeading index="06 / TRACE" title="操作留痕" subtitle="最近 100 次登录、观测录入、任务创建与发布记录。"/><ErrorNotice :message="error" @retry="refresh"/><div class="table-wrap"><table><thead><tr><th>时间</th><th>操作者</th><th>动作</th><th>对象</th></tr></thead><tbody><tr v-for="a in items" :key="a.id"><td>{{dateTime(a.created_at)}}</td><td>{{a.actor}}</td><td>{{a.action}}</td><td>{{a.target}}</td></tr></tbody></table></div></template>
